typedef struct {
    int used;
    unsigned long long id;
    pid_t process_id;
    int pty_fd;
    unsigned long long revision;
    char display_id[128];
    char pane_id[128];
    char state[16];
    char surface_id[128];
    int exit_code;
    int child_exited;
    int surface_retired;
    int focused;
    int surface_mode;
    /* External Hibr surfaces need the same attach-time reassert that a real
       terminal performs after establishing its PTY geometry.  Schedule it
       after startup output has made the desktop session live; do not inject a
       user key such as Escape, which has desktop meaning. */
    int attach_reassert_pending;
    uint64_t attach_reassert_due_us;
    int attach_reassert_attempts;
    int attach_reassert_max_attempts;
    int attach_reassert_hibr_matches;
    int hibr_process;
    int hibr_desktop_primary;
    int hibr_desktop_join;
    char hibr_desktop_session[128];
    pid_t hibr_owner_pid;
    int hibr_owner_registered;
    int hibr_resume_requested;
    int hibr_attach_unresolved;
    /* Cell requests the owner has had accepted for this session's surface,
       and when it registered. A desktop whose owner registered and then never
       painted is the blank-but-healthy state of issue #32, and these are what
       make it visible instead of a guess. */
    unsigned long long hibr_owner_writes;
    uint64_t hibr_owner_registered_us;
    int hibr_unpainted_reported;
    char hibr_session_token[64];
    int terminal_escape;
    /* Hibr emits a single SGR containing bold plus truecolor foreground and
       background (three decimal components each).  A 32-byte buffer cuts
       that sequence in the middle and leaks its tail as terminal text. */
    char terminal_csi[128];
    int terminal_csi_length;
    /* PTY reads may split a UTF-8 scalar between system calls. Keep a valid
       leading prefix until the next read instead of converting it to '?'. */
    unsigned char terminal_utf8_pending[4];
    int terminal_utf8_pending_length;
    int terminal_string_type;
    char terminal_string[4096];
    int terminal_string_length;
    char terminal_title[128];
    char terminal_clipboard[4096];
    char terminal_notification[1024];
    char terminal_default_foreground[32];
    char terminal_default_background[32];
    char terminal_link_uris[32][256];
    int terminal_link_count;
    uint16_t terminal_link;
    int terminal_charset_dec;
    int terminal_charset_g1_dec;
    int terminal_charset_shift;
    int terminal_charset_g0_pending;
    uint32_t terminal_last_codepoint;
    int terminal_last_width;
    uint32_t terminal_foreground;
    uint32_t terminal_background;
    /* The sixel colour registers, which belong to the session rather than to
       one DCS string: a stream may define its palette once and then send
       several images (issue #10). Built on first use so a session that never
       draws pays nothing, and dropped by RIS and DECSTR. */
    uint32_t terminal_sixel_palette[BLIT_SIXEL_COLOR_REGISTERS];
    int terminal_sixel_palette_ready;
    /* DECSDM (mode 80) and xterm's 8452. DECSDM *set* is display mode, which
       homes the image and leaves the cursor alone; reset -- the power-up
       default -- is sixel scrolling. That polarity is DEC's and current
       xterm's; xterm had it inverted for years, so the name of the mode is
       worth reading twice (issue #11). */
    int terminal_sixel_display_mode;
    int terminal_sixel_cursor_right;
    uint16_t terminal_attributes;
    int terminal_foreground_set;
    int terminal_background_set;
    int terminal_alternate;
    int terminal_saved_x;
    int terminal_saved_y;
    BlitSavedCursor terminal_saved_cursor[2];
    BlitSavedCursor terminal_alternate_saved_cursor;
    int terminal_dec_cursor_saved;
    int terminal_dec_cursor_saved_x;
    int terminal_dec_cursor_saved_y;
    int terminal_application_cursor;
    int terminal_application_keypad;
    int terminal_wrap_pending;
    int terminal_origin_mode;
    int terminal_autowrap;
    /* DECSACE: whether DECCARA and DECRARA act on a rectangle (the default)
       or on the stream between its corners. */
    int terminal_attribute_extent_stream;
    int terminal_newline_mode;
    int terminal_insert_mode;
    int terminal_alternate_mode;
    int terminal_focus_reporting;
    int terminal_bracketed_paste;
    int terminal_mouse_mode;
    int terminal_mouse_sgr;
    int terminal_synchronized;
    int terminal_frame_batch;
    /* Pixel geometry advertised to child programs and used by Kitty/Sixel.
       This is the renderer's actual cell size, including font scaling. */
    int terminal_cell_width;
    int terminal_cell_height;
    char terminal_term[64];
    uint32_t terminal_underline_color;
    int terminal_underline_color_set;
    BlitGraphicsImage graphics[BLIT_GRAPHICS_MAX_IMAGES];
    unsigned long graphics_rejected;
    unsigned long graphics_evicted;
    char graphics_last_error[64];
} BlitSession;

enum {
    BLIT_SURFACE_TERMINAL = 0,
    BLIT_SURFACE_EXTERNAL = 1,
    BLIT_SURFACE_MIRROR = 2
};

typedef struct {
    int display_count;
    BlitDisplay displays[BLIT_MAX_DISPLAYS];
    int pane_count;
    BlitPane panes[BLIT_MAX_PANES];
    int pane_columns;
    int pane_rows;
    unsigned long long topology_revision;
    int render_pending;
    uint64_t terminal_frame_quiet_until_us;
    uint64_t render_last_us;
    int render_interval_ms;
    int render_effective_interval_ms;
    uint64_t render_next_us[BLIT_MAX_DISPLAYS];
    unsigned long render_missed_deadlines[BLIT_MAX_DISPLAYS];
    int test_refresh_override;
    int session_count;
    unsigned long long next_session_id;
    BlitSession sessions[BLIT_MAX_SESSIONS];
    /* Terminal grids are allocated only for live sessions.  Keeping the
       maximum-size grid inline for every slot made an idle gateway commit a
       large amount of memory before it had a client. */
    BlitSurface *surfaces[BLIT_MAX_SESSIONS];
    unsigned long long next_frame_id;
    unsigned long long frame_revision;
    unsigned long long next_event_sequence;
    unsigned int mouse_buttons;
    /* Which keys are physically down, across every keyboard. The three
       modifier flags are derived from this: holding both Shift keys and
       releasing one left a single boolean saying Shift was up, and a device
       that disappeared mid-hold left it stuck down forever. */
    /* The cell the last motion report named, so the next sample inside the
       same cell is not reported again. */
    unsigned long long motion_report_session;
    int motion_report_column;
    int motion_report_row;
    int font_scale;
    int pointer_valid;
    int pointer_output;
    float pointer_x;
    float pointer_y;
    float previous_pointer_x;
    float previous_pointer_y;
    int previous_pointer_output;
    int pointer_dirty;
    int evdev_mouse_fds[BLIT_MAX_INPUT_DEVICES];
    char evdev_mouse_paths[BLIT_MAX_INPUT_DEVICES][128];
    int evdev_mouse_count;
    int evdev_mouse_reported[BLIT_MAX_INPUT_DEVICES];
    unsigned int evdev_mouse_buttons[BLIT_MAX_INPUT_DEVICES];
    /* open() calls the device scan has made, lifetime. The scan used to open
       every path once per kind, so this is how the reduction to one probe per
       path is measured rather than asserted. */
    unsigned long long diagnostic_evdev_scan_opens;
    int evdev_keyboard_fds[BLIT_MAX_INPUT_DEVICES];
    char evdev_keyboard_paths[BLIT_MAX_INPUT_DEVICES][128];
    int evdev_keyboard_count;
    int evdev_keyboard_reported[BLIT_MAX_INPUT_DEVICES];
    /* The most of each kind this process has ever had open. `input_device_missing`
       used to fire only when a count reached zero, which sounds like the right
       threshold until a machine has one stray HID interface left: on
       2026-10-11 a USB hub took the live host's keyboard and mouse away and
       the warning stayed silent, because a microphone's remote-control
       interface still counted as a keyboard and a pointer. Diagnostics said
       `warnings: []` while the operator had no input at all.

       A peak is per-process on purpose: it is the difference between what this
       machine had and what it has, and a restart is the deliberate way to say
       "this is the new normal". */
    int evdev_keyboard_peak;
    int evdev_mouse_peak;
    int evdev_gamepad_peak;
    int evdev_gamepad_fds[BLIT_MAX_INPUT_DEVICES];
    char evdev_gamepad_paths[BLIT_MAX_INPUT_DEVICES][128];
    int evdev_gamepad_count;
    int evdev_gamepad_reported[BLIT_MAX_INPUT_DEVICES];
    /* The opener thread's two queues, its wake pipe and the paths it has been
       asked about but has not answered for yet. */
    pthread_t opener_thread;
    int opener_running;
    pthread_mutex_t opener_lock;
    pthread_cond_t opener_wake;
    char opener_requests[BLIT_MAX_OPEN_QUEUE][128];
    int opener_request_count;
    BlitOpenedDevice opener_results[BLIT_MAX_OPEN_QUEUE];
    int opener_result_count;
    char opener_pending[BLIT_MAX_OPEN_QUEUE][128];
    int opener_pending_count;
    int scan_sweep_pending;
    int scan_sweep_announce;
    /* Issue #55: when every output last had a session on it, and whether this
       deployment expects one. A restart leaves the host with no desktop, and
       the health document said nothing. */
    int expect_desktop;
    uint64_t outputs_idle_since_us;
    int opener_notify[2];
    unsigned long long diagnostic_open_requests;
    unsigned long long diagnostic_open_requests_dropped;
    double diagnostic_max_open_ms;
    char listener_bind[64];
    int listener_port;
    int unauthenticated_network;
    int evdev_watch_fd;
    int snd_watch_fd;
    int audio_rescan_requested;
    /* The chord that stops the server from the keyboard. X11 called it zap,
       and it exists for the same reason: when the screen is wrong or input is
       not reaching anything, the operator is sitting in front of a machine
       whose only other control channel is the API they may not be able to
       get to. It is deliberately a *shutdown* and not a restart -- the unit's
       Restart=on-failure does not re-run a clean exit, so this stops the
       server and leaves it stopped.

       Programmable rather than hardwired, because which chord is safe depends
       on what else is running: a desktop that uses Ctrl+Alt+Backspace itself
       wants a different one, and a kiosk wants it disabled. */
    int shutdown_key_enabled;
    int shutdown_key_code;
    unsigned shutdown_key_modifiers;
    int evdev_rescan_requested;
    /* A rescan is the only thing that retires an absent device, and it is
       armed by inotify. A burst of removals -- a USB hub dropping thirteen
       nodes at once, which the live host did on 2026-10-11 -- coalesces into
       one flag, so the single scan can run while some of those nodes still
       exist and mark them seen. Nothing then arms another scan, and a device
       that is gone stays `present` for the life of the process: measured
       here at 56 seconds and counting, with kinds wiped to `other`.

       So a watch event also sets a resettle deadline, and the loop rescans
       once more after the burst has finished arriving. Idle cost is nothing;
       it only ever fires after a real change. */
    uint64_t evdev_resettle_us;
    float evdev_mouse_x;
    float evdev_mouse_y;
    BlitStream streams[BLIT_MAX_STREAMS];
    BlitHttpClient http_clients[BLIT_MAX_HTTP_CLIENTS];
    BlitInputRoute input_routes[16];
    unsigned long long input_routes_revision;
    BlitInputDevice input_devices[BLIT_MAX_INPUT_DEVICES];
    unsigned long long input_devices_revision;
    BlitAudioDevice audio_devices[BLIT_MAX_AUDIO_DEVICES];
    BlitAudioCard audio_cards[BLIT_MAX_AUDIO_CARDS];
    unsigned long long audio_cards_revision;
    unsigned long long audio_devices_revision;
    unsigned long long displays_revision;
    /* The physical device whose events are being dispatched right now, or
       NULL. ADR 0064 stage 3 routes per device, and the alternative was
       threading a device through keyboard_target and seven
       input_route_target call sites -- functions SDL also calls, which would
       all pass NULL. A field is honest here because the input path is
       single-threaded and synchronous: a device's events are fully dispatched
       before the next device's drain begins. The discipline that makes it
       safe is that it is set at the top of a drain and cleared at the bottom,
       so no resolution can ever see a device from a previous drain. */
    BlitInputDevice *input_source;
    BlitOutput outputs[BLIT_MAX_DISPLAYS];
    BlitIdempotency idempotency[BLIT_MAX_IDEMPOTENCY];
    BlitEventRecord event_history[BLIT_MAX_EVENT_HISTORY];
    unsigned int next_event_history;
    BlitEffectState effect;
    BlitOverlay overlays[BLIT_MAX_OVERLAYS];
    unsigned long long next_overlay_id;
    char auth_token[256];
    char command_allowlist[1024];
    int output_count;
    int sdl_ready;
    int direct_kms;
    /* Issue #69. A DRM connector's power state is read at most once a second:
       it is three ioctls per connector and nothing changes it but Blit. */
    uint64_t display_power_checked_us;
    int sdl_vsync_failures;
    char sdl_renderer_name[64];
    BlitKms *kms;
    BlitFont font;
    /* ADR 0062: the 16x16 font for cells a wide character occupies. Its
       glyph_count is zero when it could not be loaded, which is the test for
       whether a wide cell can be drawn from it. */
    BlitFont wide_font;
    char sdl_screenshot_dir[256];
    unsigned long sdl_screenshot_after;
    unsigned long sdl_frame;
    uint64_t started_us;
    unsigned long long diagnostic_frames;
    double diagnostic_last_frame_gap_ms;
    double diagnostic_max_frame_gap_ms;
    uint64_t diagnostic_frame_rate_started_us;
    uint64_t diagnostic_frame_rate_last_us;
    unsigned long long diagnostic_frame_rate_frames;
    unsigned long long diagnostic_frame_rate_last_frames;
    double diagnostic_frame_rate_hz;
    unsigned long long diagnostic_frame_rate_window_ms;
    double diagnostic_frame_rate_max_render_ms;
    unsigned long long diagnostic_frame_rate_missed_deadlines;
    unsigned long long diagnostic_frame_rate_window_sequence;
    unsigned long long diagnostic_frame_rate_window_missed_start;
    double diagnostic_frame_rate_window_max_render_ms;
    unsigned long long pixel_frames_accepted;
    unsigned long long pixel_frame_errors;
    unsigned long long pixel_frames_pending[BLIT_MAX_DISPLAYS];
    uint64_t pixel_frames_last_accepted_us;
    unsigned long long diagnostic_loop_iterations;
    unsigned long long diagnostic_terminal_reads;
    unsigned long long diagnostic_surface_commits;
    uint64_t diagnostic_surface_rate_started_us;
    uint64_t diagnostic_last_surface_commit_us;
    unsigned long long diagnostic_surface_rate_commits;
    unsigned long long diagnostic_surface_rate_last_commits;
    double diagnostic_surface_commit_hz;
    unsigned long long diagnostic_surface_commit_window_ms;
    unsigned long long diagnostic_surface_commit_window_sequence;
    double diagnostic_last_surface_commit_gap_ms;
    double diagnostic_max_surface_commit_gap_ms;
    unsigned long long diagnostic_frame_commits;
    unsigned long long diagnostic_present_calls;
    uint64_t diagnostic_last_loop_us;
    double diagnostic_last_loop_gap_ms;
    double diagnostic_max_loop_gap_ms;
    uint64_t diagnostic_loop_window_started_us;
    unsigned long long diagnostic_loop_window_ms;
    unsigned long long diagnostic_loop_window_sequence;
    double diagnostic_loop_window_max_gap_ms;
    double diagnostic_loop_window_current_max_gap_ms;
    double diagnostic_last_select_ms;
    double diagnostic_max_select_ms;
    double diagnostic_last_kms_present_ms;
    double diagnostic_max_kms_present_ms;
    double diagnostic_last_sdl_present_ms;
    double diagnostic_max_sdl_present_ms;
    double diagnostic_last_sdl_events_ms;
    double diagnostic_max_sdl_events_ms;
    double diagnostic_last_evdev_scan_ms;
    double diagnostic_max_evdev_scan_ms;
    double diagnostic_last_render_ms;
    double diagnostic_max_render_ms;
    double diagnostic_last_terminal_ms;
    double diagnostic_max_terminal_ms;
    unsigned long long diagnostic_terminal_bytes;
    unsigned long long diagnostic_pointer_cache_hits;
    unsigned long long diagnostic_pointer_cache_misses;
    unsigned long long diagnostic_input_events;
    double diagnostic_last_input_dispatch_ms;
    double diagnostic_max_input_dispatch_ms;
    unsigned long long diagnostic_evdev_mouse_events;
    unsigned long long diagnostic_evdev_mouse_syncs;
    unsigned long long diagnostic_evdev_mouse_motion_events;
    unsigned long long diagnostic_evdev_mouse_wheel_events;
    unsigned long long diagnostic_evdev_mouse_button_events;
    unsigned long long diagnostic_evdev_mouse_button_repeats_ignored;
    unsigned long long diagnostic_evdev_mouse_button_state_coalesced;
    uint64_t diagnostic_last_evdev_mouse_event_us;
    char diagnostic_last_evdev_mouse_path[128];
    /* The mouse has per-device counters and the keyboard had none, so a key
       that was read but not delivered could not be told apart from a device
       that was never opened. Both are reachable states and they have
       opposite fixes. */
    unsigned long long diagnostic_evdev_keyboard_events;
    unsigned long long diagnostic_evdev_keyboard_key_presses;
    unsigned long long diagnostic_evdev_keyboard_keys_delivered;
    unsigned long long diagnostic_evdev_keyboard_keys_undelivered;
    /* Physical input the PTY would not take. The master is nonblocking, so a
       full input queue returns EAGAIN and the bytes are gone; these say so
       instead of letting the loss be invisible. */
    unsigned long long diagnostic_input_keys_dropped;
    unsigned long long diagnostic_input_reports_dropped;
    uint64_t diagnostic_last_evdev_keyboard_event_us;
    char diagnostic_last_evdev_keyboard_path[128];
    unsigned long long diagnostic_sdl_mouse_events_discarded;
    unsigned long long diagnostic_sdl_mouse_events_processed;
    unsigned long long diagnostic_sdl_mouse_motion_events;
    unsigned long long diagnostic_sdl_mouse_button_events;
    unsigned long long diagnostic_sdl_mouse_fallback_events;
    int sdl_warp_pending;
    float sdl_warp_x;
    float sdl_warp_y;
    int sdl_warp_output;
    uint64_t sdl_warp_us;
    unsigned long long diagnostic_stream_dropped_events;
    unsigned long long diagnostic_stream_backpressure_disconnects;
    unsigned long long diagnostic_stream_queue_peak_bytes;
    unsigned long long diagnostic_log_sequence;
    int diagnostic_log_count;
    int diagnostic_log_next;
    char diagnostic_logs[BLIT_MAX_RUNTIME_LOGS][512];
    unsigned long long diagnostic_trace_sequence;
    int diagnostic_trace_count;
    int diagnostic_trace_next;
    char diagnostic_trace[BLIT_MAX_TRACE_EVENTS][768];
    int diagnostic_critical_trace_count;
    int diagnostic_critical_trace_next;
    char diagnostic_critical_trace[BLIT_MAX_TRACE_EVENTS][768];
    /* Graphics payloads get their own ring. They arrive at whatever rate the
       application sends them -- a video player through Kitty is as busy as a
       terminal redrawing -- and the critical ring exists precisely so a busy
       producer cannot evict input and render evidence. Sharing it would have
       traded one blind spot for another (issue #19). */
    int diagnostic_graphics_trace_count;
    int diagnostic_graphics_trace_next;
    char diagnostic_graphics_trace[BLIT_MAX_TRACE_EVENTS][768];
    int sdl_screenshot_written;
    uint32_t screenshot_requested_mask;
    char sdl_error[256];
    int listen_port;
    char update_token[256];
    char update_state[32];
    char update_detail[256];
    /* Graphics payloads as they enter the terminal parser, counted before
       anything can reject them. Without these, "the producer sent no image"
       and "Blit discarded the image" look identical from outside: both leave
       a session with zero images and a healthy document (issue #19). The
       trace entry beside them carries the detail; these survive its
       eviction. */
    unsigned long long graphics_payloads;
    unsigned long long graphics_payloads_kitty;
    unsigned long long graphics_payloads_sixel;
    unsigned long long graphics_payloads_rejected;
    /* ADR 0067: Blit's own settings. `settings_enabled` is 0 when
       BLIT_SETTINGS=ignore has been used to boot past a stored setting that
       locked the machine out -- the document is then left untouched, because
       an operator recovering a machine should not also lose what was in it. */
    char settings_path[256];
    int settings_enabled;
    int settings_unreadable;
    int settings_dirty;
    int settings_write_reported;
    uint64_t settings_dirty_us;
    unsigned long long settings_revision;
    char settings_document[BLIT_SETTINGS_CAPACITY];
} BlitRuntime;

static unsigned long long blit_graphics_generation;

static unsigned long long next_graphics_generation(void)
{
    ++blit_graphics_generation;
    if (blit_graphics_generation == 0)
        ++blit_graphics_generation;
    return blit_graphics_generation;
}

static int runtime_terminal_cell_width(const BlitRuntime *runtime)
{
    int value = runtime->direct_kms ? blit_kms_cell_width(runtime->kms) :
        blit_font_width(&runtime->font);
    if (value < 1) value = 8;
    return value * (runtime->font_scale > 0 ? runtime->font_scale : 1);
}

static int runtime_terminal_cell_height(const BlitRuntime *runtime)
{
    int value = runtime->direct_kms ? blit_kms_cell_height(runtime->kms) :
        blit_font_height(&runtime->font);
    if (value < 1) value = 16;
    return value * (runtime->font_scale > 0 ? runtime->font_scale : 1);
}

static void input_device_apply_repeat(BlitRuntime *runtime,
                                      BlitInputDevice *device);
static void evdev_refresh_modifiers(BlitInputDevice *device);

/* ADR 0067. Declared here because a device acquires its stored settings in
   the scan that discovers it, which is well above the settings module. */
static void settings_apply_input_device(BlitRuntime *runtime,
                                        BlitInputDevice *device);
static void settings_apply_audio_device(BlitRuntime *runtime,
                                        BlitAudioDevice *audio);
static void settings_mark_dirty(BlitRuntime *runtime);

static int display_index_for_output(const BlitRuntime *runtime,
                                    int output_index);
static int output_index_for_display_index(const BlitRuntime *runtime,
                                          int display_index);

static volatile sig_atomic_t blit_running = 1;
static volatile sig_atomic_t blit_restart_requested = 0;
/* An update install is restarted by the privileged helper's `systemctl
   restart`, not by this process. Re-exec'ing here raced that restart: systemd
   sends its one SIGTERM to the main pid, the process execs instead of
   exiting, and the unit waits out TimeoutStopSec and then SIGKILLs the whole
   cgroup -- taking an attached Hibr desktop with it, 90 seconds after the
   deployment reported success (issue #63). */
static volatile sig_atomic_t blit_update_exit_requested = 0;
#ifndef BLIT_BUILD_VERSION
#define BLIT_BUILD_VERSION "development"
#endif
static char blit_version[64] = BLIT_BUILD_VERSION;

static void render_outputs(BlitRuntime *runtime, const BlitFramePlan *plan,
                           uint32_t output_mask);
static SDL_Texture *create_sdl_glyph_atlas(SDL_Renderer *renderer,
                                           const BlitFont *font,
                                           int *columns_out);
static const char *pane_surface_id(const BlitRuntime *runtime,
                                   const BlitPane *pane);
static void discover_panes(BlitRuntime *runtime);
